// Reduce one Error Trigger item to one closed row (#288 option (c), owner 20 Nov 2026).
// The Error Trigger item can carry item data: the error's message, description, context and cause,
// and the failed node's parameters, all come from the failed run, and a runtime error message can
// quote its input (a JSON parse error does). So no text is copied from it. Only exact matches
// against the closed lists below, or IDs that pass a strict shape check, reach the row; anything
// else becomes a fixed fallback (EG_MONITOR_UNCLASSIFIED, 'other', '' or 'unknown'). The row is
// workflow_id, execution_id, failed_node, code, mode and failed_at: no item data, no message text.
const CODES = [
  'EG_MONITOR_REPORT_SHAPE', 'EG_MONITOR_SCHEMA', 'EG_MONITOR_RUN_ID', 'EG_MONITOR_TIMESTAMP',
  'EG_MONITOR_OLD_REPORT', 'EG_MONITOR_STREAMS', 'EG_MONITOR_STREAM_SHAPE', 'EG_MONITOR_RESULT',
  'EG_MONITOR_OK_FIELDS', 'EG_MONITOR_REF', 'EG_MONITOR_INCIDENT',
];
const NODES = [
  'Local Authenticated Report', 'Validate Both Streams and Classify', 'Five Minute Local Monitor Tick',
  'Check Missing Run (PC-On Only)', 'Alerts Disabled Until Qualified', 'One Attempt Per Incident',
  'Send Owner Alert Email',
];
const MODES = ['webhook', 'trigger', 'retry', 'internal', 'integrated', 'cli', 'error', 'evaluation', 'chat'];

const text = (value) => (typeof value === 'string' ? value : '');
const pick = (value, list, fallback) => (list.includes(value) ? value : fallback);
const obj = (value) => (value !== null && typeof value === 'object' && !Array.isArray(value) ? value : null);

const first = $input.all()[0];
const data = obj(first && first.json) || {};
const workflow = obj(data.workflow) || {};
const execution = obj(data.execution);
const trigger = obj(data.trigger);
const workflowId = /^[A-Za-z0-9]{1,64}$/.test(text(workflow.id)) ? workflow.id : 'unknown';

// The editor's sample item (#288, 22 Nov 2026): run by hand in the n8n editor, the Error Trigger has no real
// input, so n8n 2.48.5 feeds its fixed example item (ErrorTrigger.node.ts, execute(): workflow.id '1',
// execution.id 231, execution.mode 'manual'). n8n never calls an error workflow for a manual run
// (execution-lifecycle-hooks.ts: dispatchesErrorWorkflow = !isManualMode && ...), so a real failure never
// carries mode 'manual'. Only that exact triple writes no row (no item goes on, so Record Failure Row does
// not run); any other item, a near miss included, still writes its row.
if (execution && workflow.id === '1' && String(execution.id) === '231' && execution.mode === 'manual') {
  return [];
}

let row;
if (execution) {
  const error = obj(execution.error) || {};
  const id = typeof execution.id === 'number' ? String(execution.id) : text(execution.id);
  const node = text(execution.lastNodeExecuted);
  row = {
    workflow_id: workflowId,
    execution_id: /^[0-9]{1,20}$/.test(id) ? id : '',
    failed_node: node === '' ? '' : pick(node, NODES, 'other'),
    // n8n 2.48.5 runs the Code node in its task runner, which appends ' [line N]' (or
    // ' [line N, for item M]') to the thrown message (execution-error.ts). Only the bare code or
    // the code plus exactly that suffix is classified; anything else is EG_MONITOR_UNCLASSIFIED.
    code: pick((/^(EG_MONITOR_[A-Z_]+)(?: \[line \d+(?:, for item \d+)?\])?$/.exec(text(error.message).trim()) || [])[1], CODES, 'EG_MONITOR_UNCLASSIFIED'),
    mode: pick(text(execution.mode), MODES, 'other'),
  };
} else {
  // n8n sends `trigger` instead of `execution` when the trigger itself failed (no execution exists).
  row = {
    workflow_id: workflowId,
    execution_id: '',
    failed_node: '',
    code: 'EG_MONITOR_TRIGGER_FAILED',
    mode: trigger ? pick(text(trigger.mode), MODES, 'other') : 'other',
  };
}
row.failed_at = new Date(Date.now()).toISOString();
return [{ json: { row } }];
